import{_ as t,o,a,d as n}from"./chunks/framework.IehvnstE.js";const p=JSON.parse('{"title":"Mod Collections","description":"Mod collections in Stuzhik — version-independent sets of mods you can apply to any instance with one click.","frontmatter":{"description":"Mod collections in Stuzhik — version-independent sets of mods you can apply to any instance with one click.","head":[["meta",{"name":"keywords","content":"stuzhik mod collections, stuzhik, mod collections, minecraft mod sets, apply mods to instance"}]]},"headers":[],"relativePath":"en/guide/collections.md","filePath":"en/guide/collections.md"}'),i={name:"en/guide/collections.md"};function l(s,e,r,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="mod-collections" tabindex="-1">Mod Collections <a class="header-anchor" href="#mod-collections" aria-label="Permalink to &quot;Mod Collections&quot;">​</a></h1><p>Your own set of mods not tied to a game version: put it together once and apply it to any instance, and Stuzhik picks the right mod versions by itself.</p><p>It is not a modpack: a collection holds <strong>only the list of mods</strong> you usually install together, no configs or settings.</p><h2 id="why-you-need-it" tabindex="-1">Why you need it <a class="header-anchor" href="#why-you-need-it" aria-label="Permalink to &quot;Why you need it&quot;">​</a></h2><p>A modpack pins versions, a collection doesn&#39;t. If you have a go-to set (say, optimization and QoL) and often create instances for different Minecraft versions, there is no need to reinstall it by hand each time: apply the collection, and <strong>the versions are picked for that instance by themselves</strong>.</p><h2 id="creating-one" tabindex="-1">Creating one <a class="header-anchor" href="#creating-one" aria-label="Permalink to &quot;Creating one&quot;">​</a></h2><h3 id="from-scratch" tabindex="-1">From scratch <a class="header-anchor" href="#from-scratch" aria-label="Permalink to &quot;From scratch&quot;">​</a></h3><ol><li>«Mod Collections» in the sidebar: type a name into the «Collection name…» field and click «+» («Create collection»). With the field empty, «+» asks for a name</li><li>A description if you like: the «Edit collection» pencil next to the name</li><li>Mods come from the built-in catalog: the «Catalog» switch above the mod list, with an «Add» button on each mod. Search and filters work as in the regular mod catalog</li></ol><h3 id="from-an-installed-instance" tabindex="-1">From an installed instance <a class="header-anchor" href="#from-an-installed-instance" aria-label="Permalink to &quot;From an installed instance&quot;">​</a></h3><ol><li>«Mod Collections» → «From instance» → pick the instance</li><li>Tick which mods to take (not necessarily all). Only <strong>Modrinth and CurseForge mods</strong> are listed: a local JAR can&#39;t be matched to another game version</li><li>Where to: «To a new collection» (give it a name) or «To “…”», the collection open right now. Then «Add»</li></ol><h2 id="applying-one" tabindex="-1">Applying one <a class="header-anchor" href="#applying-one" aria-label="Permalink to &quot;Applying one&quot;">​</a></h2><h3 id="to-an-existing-instance" tabindex="-1">To an existing instance <a class="header-anchor" href="#to-an-existing-instance" aria-label="Permalink to &quot;To an existing instance&quot;">​</a></h3><ol><li>Instance → the «Mods» tab → the «Mod Collections» button (tooltip «Apply»)</li><li>Choose a collection</li><li>Stuzhik shows a preview: what will be installed, what will be skipped (already there or incompatible) and what was not found for this version or loader</li><li>Confirm with «Install selected»</li></ol><h3 id="when-creating-an-instance" tabindex="-1">When creating an instance <a class="header-anchor" href="#when-creating-an-instance" aria-label="Permalink to &quot;When creating an instance&quot;">​</a></h3><p>The instance creation form has an optional «Mod collection» field (it shows up once you have collections, and not for a vanilla instance). <strong>The mods are installed right after the instance is created</strong>, with versions picked for its Minecraft version and loader.</p><h2 id="export-and-import" tabindex="-1">Export and import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to &quot;Export and import&quot;">​</a></h2><ul><li><strong>To a modpack.</strong> A collection can be exported to <code>.mrpack</code> (Modrinth) or <code>.stzhk</code> (the Stuzhik format), pinning the versions for one Minecraft version</li><li><strong>A modpack into a collection.</strong> The other way around too: take an existing modpack (Modrinth or CurseForge) and save its mod list as a collection not tied to a version</li></ul><h2 id="management" tabindex="-1">Management <a class="header-anchor" href="#management" aria-label="Permalink to &quot;Management&quot;">​</a></h2><ul><li><strong>Duplicate</strong> to make a variation without touching the original</li><li><strong>Rename and a custom icon</strong></li><li><strong>Sort the mods</strong> within a collection: «By date added», «By name» or «By source»</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/en/guide/mods.html">Mods</a></li><li><a href="/en/guide/modpacks.html">Modpacks</a></li><li><a href="/en/faq.html">FAQ</a></li></ul>',21)])])}const u=t(i,[["render",l]]);export{p as __pageData,u as default};
